select jsonb_build_object('work',(select jsonb_agg(jsonb_build_object('id',w.display_id,'status',w.status,'owner',w.final_owner_member_id,'submitted',(select count(*) from public.creative_kpi_brief_evidence e where e.work_item_id=w.id and action='submitted'),'accepted',(select count(*) from public.creative_kpi_brief_evidence e where e.work_item_id=w.id and action='accepted'),'kpi',(select count(*) from public.flowmate_kpi_work_items_v k where k.id=w.id),'creative_kpi',(select count(*) from public.flowmate_creative_kpi_facts_v k where k.work_item_id=w.id),'gantt',(select count(*) from public.flowmate_team_schedule_v g where g.work_item_id=w.id),'allocation',(select count(*) from public.flowmate_capacity_allocations a where a.work_item_id=w.id))) from public.work_items w where display_id in ('CR-1243','CR-1264','CR-1265','CR-1266','CR-1267')),'ops_members',(select jsonb_agg(u.display_name) from public.users u join public.user_team_memberships m on m.user_id=u.id where m.team_code='ops' and u.is_active),'flags',(select jsonb_build_object('test',test_enabled,'production',production_enabled,'notifier',notifier_enabled) from activity_automation_private.settings));
